import {profileOf,noteKey} from './store.js';
// Personal order changes only in the browser; public grades and collection are intact.
export function personalize(papers,notes,radar,approved=[]){const map=new Map(notes.map(n=>[n.key,n]));return papers.map(p=>{const profile=profileOf(map.get(noteKey(p)),radar);const terms=approved.filter(t=>(p.title+' '+(p.abstract||'')).toLowerCase().includes(t.toLowerCase()));const score=profile.relevance*2+profile.inspiration+Math.min(terms.length,3);return {...p,personalScore:score,personalReason:score?`个人排序：本 Radar 相关性${profile.relevance||'未评'}、启发性${profile.inspiration||'未评'}${terms.length?'；已审核关注词 '+terms.join(' / '):''}。公共等级不变。`:''};}).sort((a,b)=>b.personalScore-a.personalScore||a.grade.localeCompare(b.grade)||b.date.localeCompare(a.date));}
